    long  m_b;                                     // +0x04
    float m_x;                                     // +0x08 (read by 0x00837060)
};
struct CMeshDataBank {
    unsigned char _pad[0xe6];
    CMeshInfoSize m_size;                          // +0xe6
};
#pragma pack(pop)

CMeshDataBank* GetMeshBank();                      // 0x004C79A0

struct CThingTrackNode {
    long GetDrawRecordA();
};

long CThingTrackNode::GetDrawRecordA()
{
